import { describe, it, expect } from 'vitest';
import { wordCount } from '../src/index.js';

describe('wordCount', () => {
  it('test_counts_words', () => {
    expect(wordCount('the quick  brown\tfox')).toBe(4);
  });

  it('test_empty_text', () => {
    expect(wordCount('   ')).toBe(0);
  });
});

import { describe, it, expect } from 'vitest';
import { readingTime } from '../src/index.js';

const words = (n) => Array(n).fill('word').join(' ');

describe('readingTime', () => {
  it('test_rounds_up', () => {
    expect(readingTime(words(201))).toBe(2);
  });

  it('test_custom_speed', () => {
    expect(readingTime(words(300), { wordsPerMinute: 100 })).toBe(3);
  });

  it('test_empty_text', () => {
    expect(readingTime('')).toBe(0);
  });
});

import { wordCount } from './word-count.js';

export function readingTime(str, { wordsPerMinute = 200 } = {}) {
  return Math.ceil(wordCount(str) / wordsPerMinute);
}
